import {openDb} from './db.js';import bcrypt from 'bcryptjs';import {randomUUID} from 'node:crypto';
const {ADMIN_NAME:name,ADMIN_EMAIL:email,ADMIN_PASSWORD:password}=process.env;if(!name||!/^\S+@\S+\.\S+$/.test(email||'')||!password||password.length<16||Buffer.byteLength(password,'utf8')>72)throw Error('Provide ADMIN_NAME, ADMIN_EMAIL and a unique 16–72 character ADMIN_PASSWORD');const db=openDb(process.env.DB_PATH||'./data/live.sqlite');if(db.prepare("SELECT id FROM users WHERE role='admin'").get())throw Error('An administrator already exists; bootstrap refused');db.prepare('INSERT INTO users(id,name,email,password,role) VALUES(?,?,?,?,?)').run(randomUUID(),name,email.toLowerCase(),bcrypt.hashSync(password,12),'admin');db.close();console.log('Administrator created. Remove ADMIN_PASSWORD from environment.');
